tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('./work/rows.json', 'utf8'));
const toDto = (amount) => ({ unit: 'EUR-cent', value: amount.toString() });
const settlement = rows.map(({ id, unitMinor, quantity }) => {
  assert(Number.isSafeInteger(quantity), id);
  const unit = readMinor(unitMinor);
  const net = mulDivMinor(unit, BigInt(quantity), 1n, 'half-away');
  const fee = mulDivMinor(net, 1n, 2n, 'half-away');
  return { id, net: toDto(net), fee: toDto(fee) };
});

const expected = [
  ['AR', '5', '3'],
  ['AV', '-5', '-3'],
  ['AZ', '9007199254740993', '4503599627370497'],
];
assert.deepEqual(
  settlement.map(({ id, net, fee }) => [id, net.value, fee.value]),
  expected,
);
writeFileSync('./settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
const saved = JSON.parse(readFileSync('./settlement.json', 'utf8'));
assert.deepEqual(saved.map(({ id }) => id), rows.map(({ id }) => id));
assert.deepEqual(
  saved.map(({ id, net, fee }) => {
    for (const amount of [net, fee]) {
      assert.deepEqual(Object.keys(amount).sort(), ['unit', 'value']);
      assert.equal(amount.unit, 'EUR-cent');
      assert.equal(readMinor(amount.value).toString(), amount.value);
    }
    return [id, net.value, fee.value];
  }),
  expected,
);
console.log('Проверены 3 строки, точные суммы и формат DTO.');
NODE"
